#!/bin/bash
set -euo pipefail
[[ $(id -u) == 0 ]] || { echo "Run with sudo"; exit 1; }
python3 - <<'PYBRAND'
ART=''
ICON=''
CSS='/* PiShield v0.5.3 — native template branding */\nbody .main-header a.logo .logo-lg,body .main-header a.logo .logo-mini {font-size:0!important;line-height:50px!important;letter-spacing:0!important;}\nbody .main-header a.logo img.ps-brand-header {display:inline-block!important;width:48px!important;height:48px!important;max-width:100%!important;object-fit:contain!important;vertical-align:middle!important;margin:0!important;filter:none!important;}\nbody .main-sidebar .sidebar .user-panel {display:flex!important;align-items:center!important;gap:9px!important;position:relative!important;box-sizing:border-box!important;height:auto!important;min-height:112px!important;max-height:none!important;overflow:visible!important;padding:12px 7px!important;}\nbody .main-sidebar .sidebar .user-panel:before,body .main-sidebar .sidebar .user-panel:after {display:none!important;content:none!important;}\nbody .main-sidebar .sidebar .user-panel .image {float:none!important;flex:0 0 76px!important;width:76px!important;margin:0!important;padding:0!important;}\nbody .main-sidebar .sidebar .user-panel .image img {width:76px!important;height:76px!important;max-width:100%!important;object-fit:contain!important;filter:none!important;}\nbody .main-sidebar .sidebar .user-panel .info {float:none!important;flex:1 1 0!important;min-width:0!important;position:static!important;inset:auto!important;height:auto!important;max-height:none!important;overflow:visible!important;white-space:normal!important;overflow-wrap:anywhere!important;line-height:1.5!important;padding:0!important;margin:0!important;font-size:12px!important;}\nbody .main-sidebar .sidebar .user-panel .info p {margin:0 0 5px!important;line-height:1.5!important;}\nbody .main-sidebar .sidebar .user-panel .info span {white-space:normal!important;line-height:1.5!important;}\nbody .main-sidebar .sidebar-menu {clear:both!important;position:relative!important;}\n@media(min-width:768px){body.sidebar-mini.sidebar-collapse .main-sidebar:not(:hover) .sidebar .user-panel{justify-content:center!important;padding:6px 2px!important;min-height:52px!important;}body.sidebar-mini.sidebar-collapse .main-sidebar:not(:hover) .sidebar .user-panel .info{display:none!important;}body.sidebar-mini.sidebar-collapse .main-sidebar:not(:hover) .sidebar .user-panel .image{flex-basis:42px!important;width:42px!important;}body.sidebar-mini.sidebar-collapse .main-sidebar:not(:hover) .sidebar .user-panel .image img{width:42px!important;height:42px!important;}}\nbody .login-logo img.loginpage-logo {width:min(300px,90%)!important;height:auto!important;aspect-ratio:1!important;object-fit:contain!important;filter:none!important;}\nbody .login-logo .panel-title {display:none!important;}\nbody .user-menu .user-header img.logo-img {width:76px!important;height:76px!important;object-fit:contain!important;filter:none!important;}\nbody .login-footer,body .login-donate,body .main-footer,body .menu-donate,body .ps-hide-donation,body .user-footer a[href^="http"] {display:none!important;}\nbody .sidebar-menu > li.header:has(+li.menu-donate) {display:none!important;}\nbody a[href*="pi-hole.net/donate"],body a[href*="pishield.net/donate"] {display:none!important;}\n'
import base64, os, re, shutil, tempfile, subprocess, sys
from pathlib import Path
R=Path(os.environ.get('PISHIELD_WEBROOT','/var/www/html/admin'))
B=Path(os.environ.get('PISHIELD_BACKUPS','/var/backups/pishield'))
H=R/'scripts/lua/header.lp'; A=R/'scripts/lua/header_authenticated.lp'; S=R/'scripts/lua/sidebar.lp'; L=R/'login.lp'
for p in (H,A,S,L):
    if not p.is_file() or p.is_symlink(): raise SystemExit(f'Missing native template: {p}; nothing changed')
img='img/pishield-art-v053.png'; fav='img/pishield-icon-v053.png'; css='style/pishield-brand-v053.css'
# Server-rendered branding: no JavaScript mutation or external requests.
old_assets=re.compile(r'^.*(?:pishield-(?:sentinel(?:-brand)?|brand-v05[23])\.(?:css|js)).*\n?',re.M)
def clean(s):
    return old_assets.sub('',s)
def logo_markup(cls):
    return f'<span class="{cls}"><img class="ps-brand-header" src="<?=webhome?>{img}" alt="PiShield" width="48" height="48"></span>'
def replace_span(s,cls):
    # Both the native split title and earlier image-based patch fit this pattern.
    p=r'<span\s+class="'+cls+r'"[^>]*>.*?</span>'
    s,n=re.subn(p,lambda _:logo_markup(cls),s,count=1,flags=re.S)
    if n!=1: raise SystemExit(f'Cannot locate {cls} in native template; nothing changed')
    return s
def replace_images(s):
    s=re.sub(r'img/(?:logo\.svg|pishield-sentinel\.svg|pishield-emblem-v052\.png|pishield-art-v053\.png)',img,s)
    return re.sub(r'alt="(?:Pi-hole|PiShield)\s+logo"', 'alt="PiShield"',s,flags=re.I)
def inject_css(s):
    line=f'<link rel="stylesheet" href="<?=webhome?>{css}?v=053">\n'
    # Shared header in v6.6.1 intentionally has no closing head.
    if '</head>' in s: return s.replace('</head>',line+'</head>',1)
    return s.rstrip()+'\n'+line
h=clean(H.read_text())
h,n=re.subn(r'<title>.*?</title>', '<title>PiShield | <?=hostname?></title>',h,count=1,flags=re.S)
if n!=1: raise SystemExit('Native title not found; nothing changed')
# Replace native icons, leaving manifest and theme variables alone.
h=re.sub(r'img/favicons/(?:apple-touch-icon\.png|favicon-(?:16|32)x(?:16|32)\.png|favicon\.ico|safari-pinned-tab\.svg|mstile-150x150\.png)',fav,h)
h=re.sub(r'img/pishield-(?:favicon-v052\.png|sentinel\.svg|icon-v053\.png)',fav,h)
# Keep one standards-compliant icon tag; remove mask icon (PNG is not an SVG mask).
h=re.sub(r'^.*<link rel="mask-icon".*\n?', '',h,flags=re.M)
if fav not in h: h=h.replace('</title>','</title>\n<link rel="icon" type="image/png" href="<?=webhome?>'+fav+'">',1)
h=inject_css(h)
a=replace_images(clean(A.read_text())); a=replace_span(a,'logo-mini'); a=replace_span(a,'logo-lg')
a=a.replace('Open Source Ad Blocker','PiShield Network Defense')
# Preserve logout and menu logic; hide only upstream promotional links with CSS.
s=replace_images(clean(S.read_text()))
l=replace_images(clean(L.read_text())); l=replace_span(l,'logo-lg')
# Login artwork is the primary logo, so the redundant title row is hidden in CSS.
for name,v in [('header',a),('sidebar',s),('login',l)]:
    if img not in v: raise SystemExit(f'Image path absent from {name}; nothing changed')
# Branding assets are bundled, not fetched from the internet.
updates={H:h.encode(),A:a.encode(),S:s.encode(),L:l.encode(),R/img:base64.b64decode(ART),R/fav:base64.b64decode(ICON),R/css:CSS.encode()}
for p in updates:
    if p.is_symlink() or not p.parent.is_dir(): raise SystemExit(f'Unexpected path: {p}')
B.mkdir(parents=True,exist_ok=True); backup=Path(tempfile.mkdtemp(prefix='brand-v053-',dir=B))
original={p:p.read_bytes() if p.exists() else None for p in updates}
for p,v in original.items():
    if v is not None:
        dest=backup/p.relative_to(R);dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dest)
def atomic(p,data):
    fd,tmp=tempfile.mkstemp(dir=p.parent)
    try:
        with os.fdopen(fd,'wb') as f:f.write(data)
        os.chmod(tmp,0o644);os.replace(tmp,p)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
try:
    for p,v in updates.items():atomic(p,v)
    for p,v in updates.items():
        if p.read_bytes()!=v: raise IOError(f'Verification failed: {p}')
except BaseException:
    for p,v in original.items():
        if v is None:p.unlink(missing_ok=True)
        else:atomic(p,v)
    raise
print('PiShield v0.5.3: native header, login, sidebar, favicon and stylesheet verified on disk.')
print('Backup:',backup)
print('Refresh /admin/ with Ctrl+F5. DNS service and authentication unchanged.')

PYBRAND
